    candidates = []
    for r in range(h):
        for c in range(w - 2):
            cells = [(r, c + i) for i in range(3)]
            if all(grid[rr][cc] != background for rr, cc in cells) and (r in (0, h - 1) or c == 0 or c + 2 == w - 1):
                candidates.append((cells, (0, 1)))
    for r in range(h - 2):
        for c in range(w):
            cells = [(r + i, c) for i in range(3)]
            if all(grid[rr][cc] != background for rr, cc in cells) and (c in (0, w - 1) or r == 0 or r + 2 == h - 1):
                candidates.append((cells, (1, 0)))
    if not candidates:
        return [row[:] for row in grid]
    cells, direction = candidates[0]
    pattern = [grid[r][c] for r, c in cells]
    seed = set(cells)

    # Markers are the most frequent non-background value not used by the seed.
    marker_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                            if grid[r][c] != background and (r, c) not in seed)
    if not marker_counts:
        return [row[:] for row in grid]
