            if grid[r][c] != marker or (r, c) in seed:
                continue
            for i, value in enumerate(pattern):
                rr, cc = r + (i - 1) * dr, c + (i - 1) * dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    return out
