def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # The three-cell motif is a contiguous line of non-background colors.
    # Prefer the line containing the rarest colors, which separates it from
    # the scattered repeated marker color.
    options = []
    for dr, dc in ((0, 1), (1, 0)):
        for r in range(h):
            for c in range(w):
                cells = [(r + i * dr, c + i * dc) for i in range(3)]
                if all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] != background for rr, cc in cells):
                    vals = [grid[rr][cc] for rr, cc in cells]
                    rarity = sum(1 / counts[v] for v in vals)
                    # Penalize a uniform line; motifs have at least two colors.
                    if len(set(vals)) > 1:
                        options.append((rarity, cells, vals, (dr, dc)))
    if not options:
        return [row[:] for row in grid]
    _, cells, pattern, (dr, dc) = max(options, key=lambda x: x[0])
    motif = set(cells)

    remaining = Counter(grid[r][c] for r in range(h) for c in range(w)
                        if grid[r][c] != background and (r, c) not in motif)
    if not remaining:
        return [row[:] for row in grid]
    marker = remaining.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker or (r, c) in motif:
                continue
